                float reflectionFactor = reflectionStrength * (1.0 - (relPos.y / smokeBounds.w) * 0.5);
                reflectionFactor *= (1.0 + sin(time * 3.0 + noise.b * 5.0) * 0.1); // Animate reflection intensity

